for (int i = (size / 2) - 1; i >= 0; i--) {
    int root = i;
    while (root < (size / 2)) {
        int smallest = root;
        int left = 2 * root + 1;
        int right = 2 * root + 2;

        if (left < size && arr[left] < arr[smallest]) {
            smallest = left;
        }

        if (right < size && arr[right] < arr[smallest]) {
            smallest = right;
        }

        if (smallest != root) {
            std::swap(arr[root], arr[smallest]);
            root = smallest;
        } else {
            break;
        }
    }
}
